svg.script:
(function () {
  var W = 340, H = 300;
  var p1 = document.getElementById('p1'), p2 = document.getElementById('p2'), ball = document.getElementById('ball');
  var scoreT = document.getElementById('score'), overlay = document.getElementById('overlay');
  var score1 = 0, score2 = 0, py = 120, cy = 120, ballx = 170, bally = 150, vx = 3, vy = 2;
  var running = false, over = false, keys = {};

  function resetBall(dir) { ballx = 170; bally = 150; vx = 3 * dir; vy = (Math.random() < 0.5 ? -1 : 1) * 2; }

  function serve() { running = true; overlay.textContent = ''; resetBall(Math.random() < 0.5 ? 1 : -1); }

  function draw() {
    p1.setAttribute('y', py);
    p2.setAttribute('y', cy);
    ball.setAttribute('cx', ballx);
    ball.setAttribute('cy', bally);
  }

  function step() {
    if (keys['ArrowUp'] || keys['w'] || keys['W']) py -= 6;
    if (keys['ArrowDown'] || keys['s'] || keys['S']) py += 6;
    py = Math.max(0, Math.min(H - 60, py));
    if (bally > cy + 22) cy += 4; else if (bally < cy + 22) cy -= 4;
    cy = Math.max(0, Math.min(H - 60, cy));
    ballx += vx; bally += vy;
    if (bally <= 4) { bally = 4; vy = -vy; }
    if (bally >= H - 4) { bally = H - 4; vy = -vy; }
    if (vx < 0 && ballx <= 26 && ballx >= 8 && bally > py - 6 && bally < py + 66) { vx = Math.min(7, -vx * 1.05); ballx = 26; }
    if (vx > 0 && ballx >= 314 && ballx <= 332 && bally > cy - 6 && bally < cy + 66) { vx = Math.min(7, -vx * 1.05); ballx = 314; }
    if (ballx < -12) { score2++; resetBall(1); }
    if (ballx > W + 12) { score1++; resetBall(-1); }
    if (score1 >= 11 || score2 >= 11) {
      running = false; over = true;
      overlay.textContent = (score1 >= 11 ? 'YOU WIN!' : 'CPU WINS') + ' · tap to restart';
    }
    scoreT.textContent = score1 + ' : ' + score2;
    draw();
  }

  document.addEventListener('keydown', function (e) {
    keys[e.key] = true;
    if (e.key === 'r' || e.key === 'R') { score1 = 0; score2 = 0; py = 120; cy = 120; over = false; scoreT.textContent = '0 : 0'; serve(); return; }
    if (!running && !over) serve();
  });
  document.addEventListener('keyup', function (e) { keys[e.key] = false; });
  document.addEventListener('mousemove', function (e) {
    var rect = document.documentElement.getBoundingClientRect();
    var scale = H / rect.height;
    py = (e.clientY - rect.top) * scale - 80 - 30;
    py = Math.max(0, Math.min(H - 60, py));
  });

  // --- Touch controls (mobile) ---
  function touchPaddle(clientY) {
    var rect = document.documentElement.getBoundingClientRect();
    var scale = H / rect.height;
    py = (clientY - rect.top) * scale - 80 - 30;
    py = Math.max(0, Math.min(H - 60, py));
  }
  document.addEventListener('touchstart', function (e) {
    e.preventDefault();
    if (over) { score1 = 0; score2 = 0; py = 120; cy = 120; over = false; scoreT.textContent = '0 : 0'; serve(); return; }
    touchPaddle(e.touches[0].clientY);
    if (!running && !over) serve();
  }, {passive: false});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); touchPaddle(e.touches[0].clientY); }, {passive: false});

  setInterval(step, 16);
  draw();
})();
